export const getHomeKitchenProducts = (): Product[] => HOME_KITCHEN_PRODUCTS;

export const getFeaturedHomeKitchenProducts = (): Product[] => 
  HOME_KITCHEN_PRODUCTS.filter(product => product.featured);

export const getHomeKitchenProductsByBadge = (badge: string): Product[] =>
  HOME_KITCHEN_PRODUCTS.filter(product => product.badge === badge);

export const getHomeKitchenProductsByPriceRange = (min: number, max: number): Product[] =>
  HOME_KITCHEN_PRODUCTS.filter(product => product.price >= min && product.price <= max);
